package com.example.code

//The majority of this code for class (both the enum and main class User) was generated by GPT-6.1 Sol, "Based on my CRC card for the User class,
// create the code for the class. Also note that Admin can switch between both User and Admin roles", 2026-10-27
enum class UserRole {
    ENTRANT,
    CAMPSITE_OWNER,
    ADMIN
}

class User(
    val deviceId: String,
    var name: String = "",
    var email: String = "",
    var phoneNumber: String = "",
    var profilePhotoUrl: String? = null,
    var notificationsEnabled: Boolean = true,
    val roles: Set<UserRole>
) {

    // Updates personal information and the profile image reference.
    fun updateProfile(
        name: String,
        email: String,
        phoneNumber: String,
        profilePhotoUrl: String? = this.profilePhotoUrl
    ) {
        this.name = name
        this.email = email
        this.phoneNumber = phoneNumber
        this.profilePhotoUrl = profilePhotoUrl
    }

    // Changes the notification opt-in or opt-out preference.
    fun updateNotificationPreference(enabled: Boolean) {
        notificationsEnabled = enabled
    }

    // Admins can access entrant, campsite-owner, and admin modes.
    fun canUseRole(role: UserRole): Boolean {
        return role in roles || UserRole.ADMIN in roles
    }
}